import{_ as i,o,c as n,ag as t}from"./chunks/framework.qJATeSSt.js";const h=JSON.parse('{"title":"Windows Code Signing (CI/CD)","description":"","frontmatter":{},"headers":[],"relativePath":"development/code-signing.md","filePath":"development/code-signing.md","lastUpdated":1795721399000}'),s={name:"development/code-signing.md"};function a(d,e,c,r,l,g){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="windows-code-signing-ci-cd" tabindex="-1">Windows Code Signing (CI/CD) <a class="header-anchor" href="#windows-code-signing-ci-cd" aria-label="Permalink to &quot;Windows Code Signing (CI/CD)&quot;">​</a></h1><p>SwitchCraft&#39;s Windows <code>.exe</code> build workflow (<code>.github/workflows/build.yml</code>) supports automated Authenticode signing using either <strong>Azure Trusted Signing</strong> or a <strong>PFX Code Signing Certificate</strong>.</p><p>When no signing secrets are configured, the signing steps are skipped cleanly with an informational notice so unsigned local/fork builds continue to succeed.</p><h2 id="option-1-azure-trusted-signing-recommended" tabindex="-1">Option 1: Azure Trusted Signing (Recommended) <a class="header-anchor" href="#option-1-azure-trusted-signing-recommended" aria-label="Permalink to &quot;Option 1: Azure Trusted Signing (Recommended)&quot;">​</a></h2><p>Configure the following repository secrets in GitHub (<strong>Settings &gt; Secrets and variables &gt; Actions</strong>):</p><ul><li><code>AZURE_SIGNING_ENDPOINT</code> (e.g. <code>https://eus.codesigning.azure.net</code>)</li><li><code>AZURE_TENANT_ID</code></li><li><code>AZURE_CLIENT_ID</code></li><li><code>AZURE_CLIENT_SECRET</code></li><li><code>AZURE_SIGNING_ACCOUNT</code></li><li><code>AZURE_CERT_PROFILE</code></li></ul><p>The workflow runs <code>azure/trusted-signing-action@v0</code> with SHA-256 digests and RFC 3161 timestamping (<code>http://timestamp.acs.microsoft.com</code>).</p><h2 id="option-2-pfx-code-signing-certificate" tabindex="-1">Option 2: PFX Code Signing Certificate <a class="header-anchor" href="#option-2-pfx-code-signing-certificate" aria-label="Permalink to &quot;Option 2: PFX Code Signing Certificate&quot;">​</a></h2><p>If you have an EV/OV <code>.pfx</code> certificate, configure:</p><ul><li><code>WINDOWS_SIGNING_CERT_B64</code>: Base64-encoded contents of your <code>.pfx</code> file.</li><li><code>WINDOWS_SIGNING_CERT_PASSWORD</code>: Certificate password.</li></ul><p>The workflow decodes the certificate to <code>$RUNNER_TEMP</code>, signs all built <code>dist/*.exe</code> binaries via Windows SDK <code>signtool.exe</code> with <code>/fd SHA256 /tr http://timestamp.digicert.com /td SHA256</code>, and removes the temporary <code>.pfx</code> file in an <code>always()</code> cleanup step.</p><h2 id="verifying-a-signed-binary" tabindex="-1">Verifying a Signed Binary <a class="header-anchor" href="#verifying-a-signed-binary" aria-label="Permalink to &quot;Verifying a Signed Binary&quot;">​</a></h2><p>On Windows, verify the signature and timestamp chain with:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">signtool verify </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pa </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v dist\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SwitchCraft.exe</span></span></code></pre></div>',14)])])}const u=i(s,[["render",a]]);export{h as __pageData,u as default};
